[CmdletBinding()]
param(
  [switch]$SkipFrozenInstall,
  [switch]$PreflightOnly
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

$Phase = "008R3B.7"
$PhaseSlug = "phase008r3b7-persistence-resume"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmssfff"

function Find-RepositoryRoot {
  $candidates = @((Get-Location).Path, $PSScriptRoot)
  foreach ($candidate in $candidates) {
    $current = [System.IO.DirectoryInfo]$candidate
    while ($null -ne $current) {
      if ((Test-Path (Join-Path $current.FullName "package.json")) -and
          (Test-Path (Join-Path $current.FullName "pnpm-workspace.yaml")) -and
          (Test-Path (Join-Path $current.FullName ".git"))) {
        return $current.FullName
      }
      $current = $current.Parent
    }
  }
  throw "Could not locate Hibeya Akal Budi repository root. Extract/run this handoff from inside the repository."
}

$RepoRoot = Find-RepositoryRoot
Set-Location $RepoRoot

$LogDir = Join-Path $RepoRoot "tools\dev\logs"
$BackupRoot = Join-Path $RepoRoot ("tools\dev\backups\{0}-{1}" -f $PhaseSlug, $Timestamp)
New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
$LogPath = Join-Path $LogDir ("{0}-{1}.log" -f $PhaseSlug, $Timestamp)
$EvidencePath = Join-Path $LogDir ("{0}-{1}-evidence.txt" -f $PhaseSlug, $Timestamp)

function Write-Log([string]$Message = "") {
  $Message | Tee-Object -FilePath $LogPath -Append
}

function Write-Section([string]$Title) {
  Write-Log ""
  Write-Log ("=" * 72)
  Write-Log $Title
  Write-Log ("=" * 72)
}

function Get-Sha256([string]$Path) {
  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
  return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Invoke-Native([string]$Title, [string]$Command) {
  Write-Section $Title
  Write-Log ("COMMAND: {0}" -f $Command)
  $global:LASTEXITCODE = 0
  cmd.exe /d /s /c $Command 2>&1 | Tee-Object -FilePath $LogPath -Append
  $code = $LASTEXITCODE
  Write-Log ("EXIT CODE: {0}" -f $code)
  if ($code -ne 0) { throw "Command failed (exit $code): $Command" }
}

function Assert-Toolchain {
  Write-Section "TOOLCHAIN PREFLIGHT"
  Write-Log ("Generated: {0}" -f (Get-Date -Format "yyyy-MM-ddTHH:mm:ssK"))
  Write-Log ("Repository: {0}" -f $RepoRoot)
  Write-Log ("PowerShell: {0}" -f $PSVersionTable.PSVersion)

  $nodeVersion = (& node --version 2>&1 | Out-String).Trim()
  if ($LASTEXITCODE -ne 0 -or -not $nodeVersion) { throw "Node.js is not available on PATH." }
  Write-Log ("Node: {0}" -f $nodeVersion)
  if ($nodeVersion -notmatch '^v24\.') { throw "Node 24.x is required. Detected: $nodeVersion" }

  $pnpmVersion = (& pnpm --version 2>&1 | Out-String).Trim()
  if ($LASTEXITCODE -ne 0 -or -not $pnpmVersion) { throw "pnpm is not available on PATH." }
  Write-Log ("pnpm: {0}" -f $pnpmVersion)

  $gitVersion = (& git --version 2>&1 | Out-String).Trim()
  if ($LASTEXITCODE -ne 0) { throw "git is not available on PATH." }
  Write-Log $gitVersion
}

$Targets = @(
    [PSCustomObject]@{
      Path = "packages\\offline\\src\\index.ts"
      BaselineSha256 = "e605e4e80f98e0fd86623e47a501ec35f658961f7ede068937a42f5a8fb52404"
      FinalSha256 = "41777fff6caa20510a4d341b874e5a1f84e7c04068a810e9afe294798f80c6fa"
      PayloadBase64 = ""
    },
    [PSCustomObject]@{
      Path = "packages\\offline\\src\\session.repository.ts"
      BaselineSha256 = "19939392da7443aae3f853e78482ab4a36278ed9d91494b86d0da6decab8a8d4"
      FinalSha256 = "d3383100945867c6fadd31e96db2b4bfa049e8116e45c4df3af532e43d847b72"
      PayloadBase64 = ""
    },
    [PSCustomObject]@{
      Path = "packages\\offline\\src\\__tests__\\learningJourney.repository.test.ts"
      BaselineSha256 = "bdc1de3f48a56b8ffc1ebadac531d854ff37cb45ca2646d23b4774c60a289e7d"
      FinalSha256 = "e6b61522bd22fef5d34b3e415351a5620725805656eec61134211528543a7d64"
      PayloadBase64 = ""
    },
    [PSCustomObject]@{
      Path = "packages\\offline\\src\\__tests__\\session.repository.test.ts"
      BaselineSha256 = "5dbb01b08c2c329080691523ed3eaf54adaf20e341027c41403db65a0afcbdd4"
      FinalSha256 = "e410a198461291b1376497d945c448cfca1b59cb1d8af5e8969c9add8731c996"
      PayloadBase64 = ""
    },
    [PSCustomObject]@{
      Path = "packages\\offline\\src\\learningJourney.repository.ts"
      BaselineSha256 = "166bcc30bfbf55f12dc3d8d3c33c52db46c8cee2ba74842a425514d670a684df"
      FinalSha256 = "933a7b67948bc543859b0c3ef338c499229de01be49679b183c199be7a021e72"
      PayloadBase64 = ""
    },
    [PSCustomObject]@{
      Path = "apps\\learner-web\\src\\features\\play\\ActivityPlayer.tsx"
      BaselineSha256 = "1d08405bc8a1bf219fe0921aa9d1084a3d01b7b56340f0dd6f2f4a0819c88090"
      FinalSha256 = "0a3cc4314faa311156890a97b5bfbca3975088295073f3d7b522969d69c8afb2"
      PayloadBase64 = ""
    }
)

$Applied = New-Object System.Collections.Generic.List[string]
$AlreadyApplied = New-Object System.Collections.Generic.List[string]
$BackedUp = New-Object System.Collections.Generic.List[string]

try {
  "HIBEYA AKAL BUDI - PHASE $Phase" | Set-Content -LiteralPath $LogPath -Encoding UTF8
  Write-Log "Persistence / Resume implementation handoff"
  Assert-Toolchain

  Write-Section "GIT STATUS - BEFORE"
  git status --short 2>&1 | Tee-Object -FilePath $LogPath -Append
  if ($LASTEXITCODE -ne 0) { throw "git status failed." }

  Write-Section "TARGET FINGERPRINT PREFLIGHT"
  foreach ($target in $Targets) {
    $absolute = Join-Path $RepoRoot $target.Path
    if (-not (Test-Path -LiteralPath $absolute -PathType Leaf)) {
      throw "Required target is missing: $($target.Path)"
    }
    $actual = Get-Sha256 $absolute
    Write-Log ("{0}`n  current : {1}`n  expected: {2}`n  final   : {3}" -f $target.Path, $actual, $target.BaselineSha256, $target.FinalSha256)
    if ($actual -eq $target.FinalSha256) {
      $AlreadyApplied.Add($target.Path)
      continue
    }
    if ($actual -ne $target.BaselineSha256) {
      throw "TARGET DRIFT: $($target.Path) differs from both the captured R3B.7 preflight and the intended final file. Refusing to overwrite local work."
    }
  }

  Write-Log ""
  Write-Log ("Preflight result: PASS ({0} target(s) ready; {1} already applied)." -f ($Targets.Count - $AlreadyApplied.Count), $AlreadyApplied.Count)
  if ($PreflightOnly) {
    Write-Log "PHASE 008R3B.7 PREFLIGHT-ONLY: PASS"
    Copy-Item -LiteralPath $LogPath -Destination $EvidencePath -Force
    Write-Host "Preflight PASS. Log: $LogPath"
    exit 0
  }

  if ($Targets.Count -gt $AlreadyApplied.Count) {
    Write-Section "BACKUP OWNED TARGETS"
    New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
    foreach ($target in $Targets) {
      if ($AlreadyApplied.Contains($target.Path)) { continue }
      $source = Join-Path $RepoRoot $target.Path
      $dest = Join-Path $BackupRoot $target.Path
      New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
      Copy-Item -LiteralPath $source -Destination $dest -Force
      $BackedUp.Add($target.Path)
      Write-Log ("BACKUP: {0} -> {1}" -f $target.Path, $dest)
    }

    Write-Section "APPLY PHASE 008R3B.7"
    foreach ($target in $Targets) {
      if ($AlreadyApplied.Contains($target.Path)) {
        Write-Log ("SKIP ALREADY APPLIED: {0}" -f $target.Path)
        continue
      }
      $absolute = Join-Path $RepoRoot $target.Path
      $bytes = [Convert]::FromBase64String($target.PayloadBase64)
      [System.IO.File]::WriteAllBytes($absolute, $bytes)
      $after = Get-Sha256 $absolute
      if ($after -ne $target.FinalSha256) { throw "Post-write hash mismatch: $($target.Path)" }
      $Applied.Add($target.Path)
      Write-Log ("APPLIED: {0} [{1}]" -f $target.Path, $after)
    }
  } else {
    Write-Section "APPLY PHASE 008R3B.7"
    Write-Log "All owned targets already match the intended R3B.7 state. No file rewrite required."
  }

  if (-not $SkipFrozenInstall) {
    Invoke-Native "VERIFY FROZEN LOCKFILE / WORKSPACE LINKS" "pnpm install --frozen-lockfile"
  } else {
    Write-Section "VERIFY FROZEN LOCKFILE / WORKSPACE LINKS"
    Write-Log "SKIPPED by -SkipFrozenInstall"
  }

  Invoke-Native "OFFLINE PERSISTENCE TESTS" "pnpm --filter @akal-budi/offline test"
  Invoke-Native "OFFLINE TYPECHECK" "pnpm --filter @akal-budi/offline typecheck"
  Invoke-Native "LEARNER WEB TYPECHECK" "pnpm --filter learner-web typecheck"
  Invoke-Native "TARGETED LEARNER TESTS" "pnpm --filter learner-web test -- --run src/features/play/selectLearnerActivity.test.ts src/journey/learnerJourney.test.ts src/journey/learnerProgress.test.ts"
  Invoke-Native "CONTENT COMPILER REPRODUCIBILITY" "pnpm content:check"

  Write-Section "FINAL TARGET FINGERPRINTS"
  foreach ($target in $Targets) {
    $actual = Get-Sha256 (Join-Path $RepoRoot $target.Path)
    Write-Log ("{0}  {1}" -f $actual, $target.Path)
    if ($actual -ne $target.FinalSha256) { throw "Final integrity check failed: $($target.Path)" }
  }

  Write-Section "GIT STATUS - AFTER"
  git status --short 2>&1 | Tee-Object -FilePath $LogPath -Append
  if ($LASTEXITCODE -ne 0) { throw "Final git status failed." }

  Write-Section "PHASE SUMMARY"
  Write-Log ("Applied files: {0}" -f $Applied.Count)
  Write-Log ("Already applied: {0}" -f $AlreadyApplied.Count)
  Write-Log ("Backups created: {0}" -f $BackedUp.Count)
  if ($BackedUp.Count -gt 0) { Write-Log ("Backup root: {0}" -f $BackupRoot) }
  Write-Log "PHASE 008R3B.7: PASS"
  Copy-Item -LiteralPath $LogPath -Destination $EvidencePath -Force
  Write-Host ""
  Write-Host "PHASE 008R3B.7: PASS"
  Write-Host "Log: $LogPath"
  Write-Host "Evidence: $EvidencePath"
  exit 0
}
catch {
  Write-Section "PHASE FAILURE"
  Write-Log "PHASE 008R3B.7: FAILED"
  Write-Log ("ERROR: {0}" -f $_.Exception.Message)
  Write-Log ("POSITION: {0}" -f $_.InvocationInfo.PositionMessage)
  if ($BackedUp.Count -gt 0) {
    Write-Log ("Backups preserved at: {0}" -f $BackupRoot)
    Write-Log "No automatic rollback was performed; this avoids overwriting unrelated working-tree changes."
  }
  try {
    Write-Section "GIT STATUS - FAILURE"
    git status --short 2>&1 | Tee-Object -FilePath $LogPath -Append
  } catch {}
  try { Copy-Item -LiteralPath $LogPath -Destination $EvidencePath -Force } catch {}
  Write-Host ""
  Write-Host "PHASE 008R3B.7: FAILED" -ForegroundColor Red
  Write-Host "Log: $LogPath"
  Write-Host "Evidence: $EvidencePath"
  exit 1
}
